#include <stdio.h>

int main() {
    int n;
    long long k;
    scanf("%d %lld", &n, &k);
    long long a[n];
    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);

    int low = 0, high = n - 1, ans = -1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (a[mid] == k) {
            ans = mid;
            break;
        } else if (a[mid] < k) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    printf("%d\n", ans);
    return 0;
}

